const CRS = Object.fromEntries(Object.entries(CR).map(([k, b]) => [k, { name: b.name, CBR: nums(b.CBR), CDR: nums(b.CDR), CNMR: nums(b.CNMR), r: nums(b.r) }]));
const WP = { P: nums(WORLD.P), r: nums(WORLD.r) };
const DECADES = [1950, 1960, 1970, 1980, 1990, 2000, 2010, 2020];
/** Compact flow label from thousands: "738k", "1.18M", "25.3k". */
const kf = (k) => { const a = Math.abs(k); return a >= 1000 ? `${fx(a / 1000, 2)}M` : a >= 100 ? `${Math.round(a)}k` : `${fx(a, 1)}k`; };
/** A thick stream (width w px) along a polyline in data coordinates, with an arrowhead at the end. */
function stream(v, s, pts, w, color, alpha = 0.78) {
  if (!(w > 0.3) || pts.length < 2) return;
  const c = s.ctx, P = pts.map(([x, y]) => [s.X(x), s.Y(y)]);
  const [xa, ya] = P[P.length - 2], [xb, yb] = P[P.length - 1], L = Math.hypot(xb - xa, yb - ya) || 1, ux = (xb - xa) / L, uy = (yb - ya) / L;
  const hl = Math.min(L * 0.85, w * 0.7 + 8), hw = w / 2 + 5;
  c.save(); c.strokeStyle = v.color(color, alpha); c.lineWidth = w; c.lineJoin = 'round'; c.lineCap = 'butt';
  c.beginPath();
  P.forEach((p, i) => { const q = i === P.length - 1 ? [xb - ux * hl * 0.9, yb - uy * hl * 0.9] : p; if (i) c.lineTo(q[0], q[1]); else c.moveTo(q[0], q[1]); });
  c.stroke();
  c.fillStyle = v.color(color, alpha); c.beginPath(); c.moveTo(xb, yb);
  c.lineTo(xb - ux * hl - uy * hw, yb - uy * hl + ux * hw); c.lineTo(xb - ux * hl + uy * hw, yb - uy * hl - ux * hw); c.closePath(); c.fill();
  c.restore();
}
/** Small × marker (pixel size r). */
function cross(s, x, y, r, color, width = 2) {
  const X = s.X(x), Y = s.Y(y);
  s.line(s.invX(X - r), s.invY(Y - r), s.invX(X + r), s.invY(Y + r), { color, width });
  s.line(s.invX(X - r), s.invY(Y + r), s.invX(X + r), s.invY(Y - r), { color, width });
}

